1	/**
2	 * The cypress-realworld-app Witness calibration driver.
3	 *
4	 * The journey's selectors, routes and backend category were declared from the
5	 * application's own Cypress specs, never yet read off the live DOM+backend.
6	 * Pinning a stateful journey before the live surface has been measured is what
7	 * the TinyTranslator/Super-Productivity rounds spent passes undoing. This drives
8	 * ONE lane of the built production-static output against the application's REAL
9	 * Express-over-lowdb backend — booted through the SAME generic serving path the
10	 * proof uses (`startStaticServer` + `startLiveBackend`), so the origin/CORS
11	 * coordination this driver exercises is the product's, not a bespoke copy — and
12	 * prints every measurement: the ordered steps and their refusals, the recorded
13	 * navigations, every request outcome bucketed by origin, and the tracked-event
14	 * counts.
15	 *
16	 * It publishes nothing, asserts nothing of its own, and is not part of any
17	 * receipt. Its only output is stdout. The backend is booted in the application's
18	 * own era runtime cell (Node 14.16.1), reseeded from its frozen snapshot before
19	 * the pass, exactly as the live-backend serving path reseeds.
20	 */
21	
22	import { readFileSync } from 'node:fs';
23	import { basename, join, resolve } from 'pathe';
24	import { box, runBoxes } from '@async/witness';
25	import { joinURL, parseHost, parseURL, stringifyParsedURL } from 'ufo';
26	import { canonicalize } from '../../../core/src/receipts/canonicalize.ts';
27	import { WITNESS_REACT_CYPRESS_RWA_ACTOR } from '../../../core/src/receipts/witness-react-cypress-rwa.ts';
28	import { type LiveBackendSpec, startLiveBackend } from '../witness/live-backend.ts';
29	import { witnessNodeFileSystem } from '../witness/node-filesystem.ts';
30	import { createPlaywrightWitnessHost } from '../witness/playwright-host.ts';
31	import type { WitnessObservedRequestOutcome } from '../witness/playwright-host.ts';
32	import { startStaticServer } from '../witness/real-app-run.ts';
33	
34	const root = resolve(import.meta.dirname, '../../../..');
35	const workRoot = join(root, '.versionless/work/react-cypress-rwa');
36	const eraNodeBin = join(
37		root,
38		'.versionless/cache/react-cypress-rwa-runtime/node-v14.16.1-darwin-x64/bin',
39	);
40	const eraYarnBin = join(root, '.versionless/cache/react-cypress-rwa-baseline/npm-global/bin');
41	const chromiumExecutable = join(
42		root,
43		'.versionless/cache/react-boilerplate-v4/ms-playwright/chromium_headless_shell-1208/chrome-headless-shell-mac-arm64/chrome-headless-shell',
44	);
45	
46	const laneStaticRoot = {
47		baseline: join(workRoot, 'baseline/build-run1'),
48		migrated: join(workRoot, 'target/build-vite-run1'),
49	} as const;
50	
51	/** The application source lane the backend server is spawned from. */
52	const backendLaneRoot = join(workRoot, 'baseline');
53	const BACKEND_PORT = 3001;
54	
55	const VIEWPORT = { width: 1280, height: 900 } as const;
56	
57	/** A decodable placeholder answered in-context for the app's S3 avatar SVGs. */
58	const NON_LOOPBACK_PLACEHOLDER_SVG =
59		'<svg xmlns="http://www.w3.org/2000/svg" width="64" height="64" viewBox="0 0 64 64"><rect width="64" height="64" fill="#dddddd"/></svg>';
60	
61	/**
62	 * The application's own live-backend declaration, exactly as the AppSpec declares
63	 * it: the app's server command, the loopback host and port its built SPA
64	 * addresses, and the CORS-origin port variable the harness injects the served
65	 * port into. The era-runtime PATH is the one application-specific fact the
66	 * calibration adds — the proof's executeRun path inherits the runtime cell a
67	 * different way — so the serving/origin coordination measured here is the
68	 * generic one.
69	 */
70	const backendSpec: LiveBackendSpec = {
71		command: 'yarn',
72		args: ['start:api'],
73		cwd: '.',
74		port: BACKEND_PORT,
75		host: 'localhost',
76		corsOriginPortEnv: ['REACT_APP_PORT'],
77		env: {
78			PATH: `${eraNodeBin}:${eraYarnBin}:${process.env.PATH ?? ''}`,
79			SKIP_YARN_COREPACK_CHECK: '1',
80		},
81		seed: { snapshot: 'data/database-seed.json', store: 'data/database.json' },
82		prepare: [{ from: 'scripts/mock-aws-exports.js', to: 'src/aws-exports.js' }],
83		health: { path: '/checkAuth', okStatus: [401] },
84		readyTimeoutMs: 45_000,
85	};
86	
87	const firstLine = (error: unknown): string =>
88		(error instanceof Error ? error.message : String(error)).split('\n')[0]!.trim();
89	
90	/** Swap the host of a `http://<host>:<port>` origin, keeping the bound port. */
91	function withHost(origin: string, host: string): string {
92		const port = parseHost(parseURL(origin).host ?? '').port ?? '';
93		return stringifyParsedURL({ protocol: 'http:', host: `${host}:${port}` });
94	}
95	
96	function bucketRequests(
97		outcomes: readonly WitnessObservedRequestOutcome[],
98		staticOrigin: string,
99		backendOrigin: string,
100	): unknown {
101		const backend = new Map<string, { count: number; statuses: number[] }>();
102		const other: Array<{ method: string; url: string; status: number | null }> = [];
103		let staticCount = 0;
104		for (const outcome of outcomes) {
105			if (outcome.url.startsWith(staticOrigin)) {
106				staticCount += 1;
107				continue;
108			}
109			if (outcome.url.startsWith(backendOrigin)) {
110				const parsed = parseURL(outcome.url.slice(backendOrigin.length));
111				const path = parsed.pathname || '/';
112				const key = `${outcome.method} ${path}`;
113				const existing = backend.get(key);
114				if (existing === undefined) backend.set(key, { count: 1, statuses: [outcome.status ?? 0] });
115				else {
116					existing.count += 1;
117					if (!existing.statuses.includes(outcome.status ?? 0))
118						existing.statuses.push(outcome.status ?? 0);
119				}
120				continue;
121			}
122			other.push({ method: outcome.method, url: outcome.url, status: outcome.status });
123		}
124		return {
125			staticCount,
126			backend: [...backend.entries()]
127				.map(([key, value]) => ({ endpoint: key, ...value }))
128				.sort((left, right) => left.endpoint.localeCompare(right.endpoint)),
129			other,
130		};
131	}
132	
133	function pageSummary(receiptPath: string): unknown {
134		const receipt = JSON.parse(readFileSync(receiptPath, 'utf8')) as {
135			boxes?: Array<{ pages?: Array<Record<string, unknown>> }>;
136		};
137		const page = receipt.boxes?.[0]?.pages?.[0];
138		if (page === undefined) return null;
139		return {
140			navigations: (page.navigations as Array<{ url: string }> | undefined)?.map((navigation) => {
141				const parsed = parseURL(navigation.url);
142				return `${parsed.pathname}${parsed.hash}`;
143			}),
144			trackedEvents: Object.fromEntries(
145				Object.entries((page.trackedEvents as Record<string, unknown[]>) ?? {}).map(
146					([name, events]) => [name, events.length],
147				),
148			),
149			consoleErrors: (page.consoleMessages as Array<{ level: string }> | undefined)?.filter(
150				(message) => message.level === 'error',
151			).length,
152			pageErrors: (page.pageErrors as unknown[] | undefined)?.length,
153			failedRequests: page.failedRequests,
154		};
155	}
156	
157	export async function calibrateCypressRwaLane(lane: 'baseline' | 'migrated'): Promise<void> {
158		const actor = WITNESS_REACT_CYPRESS_RWA_ACTOR;
159		const staticRoot = laneStaticRoot[lane];
160		const receiptDir = join(root, '.versionless/stage/witness-react-cypress-rwa-calibrate', lane);
161		// The generic serving path: bind the static server first, then boot the backend
162		// with the ephemeral served SPA port injected, and address the browser at the
163		// declared host so the document origin is the one the backend's CORS allow-list
164		// admits.
165		const staticServer = await startStaticServer(staticRoot, { profile: 'current-witness' });
166		const servedOrigin = withHost(staticServer.origin, backendSpec.host ?? '127.0.0.1');
167		const servedPort = Number(parseHost(parseURL(servedOrigin).host ?? '').port ?? '');
168		const backend = await startLiveBackend(backendLaneRoot, backendSpec, { spaPort: servedPort });
169		const host = createPlaywrightWitnessHost({
170			chromiumExecutable,
171			contextProfile: 'current-witness',
172			viewport: VIEWPORT,
173			// Every non-loopback request is answered in-context so nothing leaves the
174			// machine: the application's S3 avatar SVGs get a decodable placeholder image
175			// (so the page renders clean), anything else an empty 204. The host counts
176			// all of these as mockedNonLoopback and keeps successfulNonLoopback at 0.
177			transport: async (request) => {
178				if (request.pathname.endsWith('.svg'))
179					return {
180						action: 'fulfill',
181						status: 200,
182						contentType: 'image/svg+xml',
183						body: Buffer.from(NON_LOOPBACK_PLACEHOLDER_SVG),
184					};
185				return { action: 'fulfill', status: 204, contentType: 'text/plain', body: Buffer.alloc(0) };
186			},
187		});
188		const steps: Array<{ name: string; outcome: string }> = [];
189		let status = 'unknown';
190		let failure = '';
191		let receiptPath = '';
192		const definition = box(`cypress-rwa-calibrate-${lane}`, async (context) => {
193			// Signup is reached by a real load to `/signup`: clicking the signin page's
194			// signup link does not SPA-navigate under automation (measured), so the
195			// journey navigates there directly and the SPA index fallback renders the
196			// SignUpForm. Every anchor below is a settled-reaction wait, never a sleep.
197			const page = await context.browser.visit(joinURL(servedOrigin, '/signup'));
198			await page.trackEvents('click', 'input', 'change', 'keydown', 'mouseover');
199			const expectPage = context.expect.page;
200			const record = async (name: string, fn: () => Promise<void>): Promise<void> => {
201				try {
202					await fn();
203					steps.push({ name, outcome: 'ok' });
204				} catch (error: unknown) {
205					steps.push({ name, outcome: `FAIL: ${firstLine(error)}` });
206					throw error;
207				}
208			};
209			// Settled-reaction anchor: waits (bounded, event-driven) until the selector
210			// is in the DOM. A comma selector admits either of two settled shapes — a
211			// populated list or the app's own empty-list marker — for a feed whose
212			// content depends on the actor's relationships.
213			const anchor = (name: string, selector: string): Promise<void> =>
214				record(`anchor ${name}`, () => expectPage.exists(page, selector));
215			const type = (name: string, selector: string, text: string): Promise<void> =>
216				record(`type ${name}`, () => page.type(selector, text, { redact: false }));
217			const click = (name: string, selector: string): Promise<void> =>
218				record(`click ${name}`, () => page.click(selector, { timeoutMs: 8_000 }));
219	
220			// The MUI `data-test` on signup/signin/bankaccount/transaction-create sits on
221			// the TextField ROOT, so the real <input> is `[data-test=…] input`; the
222			// settings and peer-search fields carry `data-test` on the <input> itself
223			// (inputProps), so they are addressed without the ` input` descendant. Both
224			// facts are measured against the live DOM.
225	
226			// Sign up as a fresh NON-seed actor.
227			await anchor('signup-form', '[data-test=signup-first-name] input');
228			await type('signup-first', '[data-test=signup-first-name] input', actor.firstName);
229			await type('signup-last', '[data-test=signup-last-name] input', actor.lastName);
230			await type('signup-username', '[data-test=signup-username] input', actor.username);
231			await type('signup-password', '[data-test=signup-password] input', actor.password);
232			await type('signup-confirm', '[data-test=signup-confirmPassword] input', actor.password);
233			await click('signup-submit', '[data-test=signup-submit]');
234	
235			// Sign in as it.
236			await anchor('back-to-signin', '[data-test=signin-username] input');
237			await type('signin-username', '[data-test=signin-username] input', actor.username);
238			await type('signin-password', '[data-test=signin-password] input', actor.password);
239			await click('signin-submit', '[data-test=signin-submit]');
240	
241			// Onboarding — the app's first-bank-account dialog (POST /graphql).
242			await anchor('onboarding-dialog', '[data-test=user-onboarding-next]');
243			await click('onboarding-next-1', '[data-test=user-onboarding-next]');
244			await anchor('bank-form', '[data-test=bankaccount-bankName-input] input');
245			await type('bank-name', '[data-test=bankaccount-bankName-input] input', 'Versionless Bank');
246			await type('bank-routing', '[data-test=bankaccount-routingNumber-input] input', '987654321');
247			await type('bank-account', '[data-test=bankaccount-accountNumber-input] input', '123456789');
248			await click('bank-submit', '[data-test=bankaccount-submit]');
249			await anchor('onboarding-done', '[data-test=user-onboarding-next]');
250			await click('onboarding-next-2', '[data-test=user-onboarding-next]');
251	
252			// Settings write — a fresh actor has no email/phone, so the form is invalid
253			// and Save stays disabled until both are filled; filling them and saving is
254			// the mutating PATCH /users/{created-user-id} the journey proves.
255			await anchor('home', '[data-test=sidenav-user-settings]');
256			await click('nav-settings', '[data-test=sidenav-user-settings]');
257			await anchor('settings-form', '[data-test=user-settings-email-input]');
258			await type('settings-email', '[data-test=user-settings-email-input]', 'prover@versionless.test');
259			await type('settings-phone', '[data-test=user-settings-phoneNumber-input]', '6155551234');
260			await click('settings-submit', '[data-test=user-settings-submit]');
261	
262			// Money movement — search a peer (its handle is captured and normalized, never
263			// recorded), send a payment the backend mints an id for (POST /transactions).
264			await anchor('after-settings', '[data-test=nav-top-new-transaction]');
265			await click('new-transaction', '[data-test=nav-top-new-transaction]');
266			await anchor('peer-search', '[data-test=user-list-search-input]');
267			await type('search-peer', '[data-test=user-list-search-input]', 'a');
268			await anchor('peer-results', '[data-test^=user-list-item-]');
269			await click('pick-peer', '[data-test^=user-list-item-]');
270			await anchor('amount-form', '[data-test=transaction-create-amount-input] input');
271			await type('amount', '[data-test=transaction-create-amount-input] input', '15');
272			await type(
273				'description',
274				'[data-test=transaction-create-description-input] input',
275				'versionless-proof-payment',
276			);
277			await click('submit-payment', '[data-test=transaction-create-submit-payment]');
278	
279			// The minted transaction round-trips lowdb into the actor's personal feed, and
280			// the balance settles — the substantive stateful assertion of the journey.
281			await anchor('payment-settled', '[data-test=sidenav-home]');
282			await click('home', '[data-test=sidenav-home]');
283			await click('personal-tab', '[data-test=nav-personal-tab]');
284			await anchor('personal-feed', '[data-test=transaction-list]');
285			await record('minted-tx-in-feed', () =>
286				expectPage.bodyText(page, { contains: 'versionless-proof-payment' }),
287			);
288			await record('balance-settled', () =>
289				expectPage.visible(page, '[data-test=sidenav-user-balance]'),
290			);
291	
292			// Feed filter — the three feeds the app ships. Contacts is empty for a fresh
293			// actor, so its settled shape is the app's own empty-list marker.
294			await click('public-tab', '[data-test=nav-public-tab]');
295			await anchor('public-feed', '[data-test=transaction-list]');
296			await click('contacts-tab', '[data-test=nav-contacts-tab]');
297			await anchor('contacts-feed', '[data-test=transaction-list], [data-test=empty-list-header]');
298			await click('personal-tab-2', '[data-test=nav-personal-tab]');
299			await anchor('personal-feed-2', '[data-test=transaction-list]');
300	
301			// Notifications — read the app's own notification feed (GET /notifications).
302			await click('nav-notifications', '[data-test=sidenav-notifications]');
303			await anchor(
304				'notifications-settled',
305				'[data-test=notifications-list], [data-test=empty-list-header]',
306			);
307	
308			await record('tracked-events', () =>
309				expectPage.outcome(page, {
310					events: {
311						click: { atLeast: 10 },
312						input: { atLeast: 8 },
313						keydown: { atLeast: 8 },
314					},
315				}),
316			);
317	
318			await context.receipt.capture('calibration-complete');
319		});
320		try {
321			const result = await runBoxes({
322				root: staticRoot,
323				boxes: [
324					{
325						file: join(staticRoot, 'versionless-runtime.box.ts'),
326						relativeFile: 'versionless-runtime.box.ts',
327						exportName: 'default',
328						box: definition,
329					},
330				],
331				receiptDir,
332				assertionTimeoutMs: 8_000,
333				fileSystem: witnessNodeFileSystem,
334				browser: host.browser,
335				headless: true,
336			});
337			status = result.status;
338			failure = result.boxes[0]?.error?.message ?? '';
339			receiptPath = result.receiptPath;
340		} finally {
341			await staticServer.close();
342			await backend.close();
343		}
344		process.stdout.write(
345			`${canonicalize({
346				lane,
347				status,
348				failure,
349				staticOrigin: servedOrigin,
350				backendOrigin: backend.origin,
351				steps,
352				locality: host.locality(),
353				requests: bucketRequests(host.requestOutcomes(), servedOrigin, backend.origin),
354				page: receiptPath === '' ? null : pageSummary(receiptPath),
355			})}\n`,
356		);
357	}
358	
359	export async function main(args = process.argv.slice(2)): Promise<void> {
360		const lane = args[0];
361		if (lane !== 'baseline' && lane !== 'migrated')
362			throw new Error('cypress-rwa calibration requires a lane: baseline or migrated');
363		await calibrateCypressRwaLane(lane);
364	}
365	
366	if (basename(process.argv[1] ?? '') === 'react-cypress-rwa-calibrate-run.ts')
367		main().catch((error: unknown) => {
368			process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
369			process.exitCode = 1;
370		});
