1	/**
2	 * Direct-Playwright diagnostic for the cypress-realworld-app live-backend journey.
3	 *
4	 * Unlike the witness-host calibration driver, this drives a raw Playwright page so
5	 * it can read the live DOM (`page.evaluate`), the current URL and the real network
6	 * ledger at each leg. It publishes nothing and asserts nothing; its only output is
7	 * a JSON dump on stdout used to calibrate the journey/schema pins to measured
8	 * reality. It boots the application's own Express-over-lowdb backend in its era
9	 * runtime cell, reseeded from the frozen snapshot, exactly as the serving path does.
10	 */
11	
12	import { type ChildProcess, spawn } from 'node:child_process';
13	import { copyFile } from 'node:fs/promises';
14	import { get } from 'node:http';
15	import { basename, join, resolve } from 'pathe';
16	import { chromium } from 'playwright';
17	import { canonicalize } from '../../../core/src/receipts/canonicalize.ts';
18	import { WITNESS_REACT_CYPRESS_RWA_ACTOR } from '../../../core/src/receipts/witness-react-cypress-rwa.ts';
19	import { startStaticServer } from '../witness/real-app-run.ts';
20	
21	const root = resolve(import.meta.dirname, '../../../..');
22	const workRoot = join(root, '.versionless/work/react-cypress-rwa');
23	const eraNodeBin = join(
24		root,
25		'.versionless/cache/react-cypress-rwa-runtime/node-v14.16.1-darwin-x64/bin',
26	);
27	const eraYarnBin = join(root, '.versionless/cache/react-cypress-rwa-baseline/npm-global/bin');
28	const chromiumExecutable = join(
29		root,
30		'.versionless/cache/react-boilerplate-v4/ms-playwright/chromium_headless_shell-1208/chrome-headless-shell-mac-arm64/chrome-headless-shell',
31	);
32	
33	const laneStaticRoot: Record<string, string> = {
34		baseline: join(workRoot, 'baseline/build-run1'),
35		migrated: join(workRoot, 'target/build-vite'),
36	};
37	const backendLaneRoot = join(workRoot, 'baseline');
38	const BACKEND_PORT = 3001;
39	
40	async function probeHealth(url: string): Promise<number | null> {
41		return await new Promise<number | null>((settle) => {
42			const request = get(url, (response) => {
43				settle(response.statusCode ?? null);
44				response.resume();
45			});
46			request.setTimeout(500, () => request.destroy());
47			request.on('error', () => settle(null));
48		});
49	}
50	
51	const delay = (ms: number): Promise<void> =>
52		new Promise<void>((settle) => void setTimeout(settle, ms));
53	
54	async function bootBackend(frontendPort: number): Promise<{ close(): Promise<void> }> {
55		await copyFile(
56			join(backendLaneRoot, 'data/database-seed.json'),
57			join(backendLaneRoot, 'data/database.json'),
58		);
59		const child: ChildProcess = spawn('yarn', ['start:api'], {
60			cwd: backendLaneRoot,
61			env: {
62				...process.env,
63				PATH: `${eraNodeBin}:${eraYarnBin}:${process.env.PATH ?? ''}`,
64				PORT: String(BACKEND_PORT),
65				// The CORS allow-origin the backend builds is `http://localhost:${REACT_APP_PORT}`,
66				// so it must equal the static origin the browser is actually served from.
67				REACT_APP_PORT: String(frontendPort),
68				SKIP_YARN_COREPACK_CHECK: '1',
69			},
70			stdio: 'ignore',
71		});
72		const deadline = Date.now() + 45_000;
73		while (Date.now() < deadline) {
74			if ((await probeHealth(`http://127.0.0.1:${BACKEND_PORT}/checkAuth`)) === 401) break;
75			await delay(250);
76		}
77		return {
78			close: async () =>
79				await new Promise<void>((settle) => {
80					child.once('exit', () => settle());
81					child.kill('SIGTERM');
82					setTimeout(() => {
83						if (child.exitCode === null && child.signalCode === null) child.kill('SIGKILL');
84					}, 2_000);
85				}),
86		};
87	}
88	
89	export async function probeCypressRwaLane(lane: string): Promise<void> {
90		const actor = WITNESS_REACT_CYPRESS_RWA_ACTOR;
91		const staticRoot = laneStaticRoot[lane]!;
92		const staticServer = await startStaticServer(staticRoot, { profile: 'current-witness' });
93		// The static server binds 127.0.0.1; addressing it through `localhost` yields a
94		// `http://localhost:<port>` document origin that the backend CORS allow-list can match.
95		const staticPort = Number(new URL(staticServer.origin).port);
96		const appOrigin = `http://localhost:${staticPort}`;
97		const backend = await bootBackend(staticPort);
98		const browser = await chromium.launch({ executablePath: chromiumExecutable, headless: true });
99		const context = await browser.newContext({ viewport: { width: 1280, height: 900 } });
100		const page = await context.newPage();
101		const network: Array<{ method: string; url: string; status: number | null }> = [];
102		const backendOrigin = `http://localhost:${BACKEND_PORT}`;
103		const normalize = (raw: string): string => {
104			if (raw.startsWith(backendOrigin)) return `{backend}${raw.slice(backendOrigin.length)}`;
105			return raw;
106		};
107		page.on('response', (response) => {
108			const url = response.url();
109			if (url.startsWith(appOrigin)) return;
110			network.push({
111				method: response.request().method(),
112				url: normalize(url),
113				status: response.status(),
114			});
115		});
116		page.on('requestfailed', (request) => {
117			const url = request.url();
118			if (url.startsWith(appOrigin)) return;
119			network.push({
120				method: request.method(),
121				url: normalize(url),
122				status: null,
123			});
124		});
125		const consoleErrors: string[] = [];
126		page.on('console', (message) => {
127			if (message.type() === 'error') consoleErrors.push(message.text().slice(0, 200));
128		});
129		page.on('pageerror', (error) => consoleErrors.push(`PAGEERROR ${error.message.slice(0, 200)}`));
130	
131		const dataTests = async (): Promise<string[]> =>
132			await page.evaluate(() =>
133				[...document.querySelectorAll('[data-test]')]
134					.map((element) => (element as HTMLElement).dataset.test ?? '')
135					.filter((value, index, all) => all.indexOf(value) === index)
136					.sort(),
137			);
138	
139		const legs: Array<Record<string, unknown>> = [];
140		let netCursor = 0;
141		const snapshot = async (label: string): Promise<void> => {
142			legs.push({ label, url: new URL(page.url()).pathname, dataTests: await dataTests() });
143		};
144	
145		const clickIfPresent = async (selector: string, label: string): Promise<void> => {
146			try {
147				await page.locator(selector).first().click({ timeout: 4_000 });
148				legs.push({ action: label, selector, outcome: 'clicked' });
149			} catch (error: unknown) {
150				legs.push({
151					action: label,
152					selector,
