1	import { canonicalize, sha256 } from './canonicalize.ts';
2	import {
3		WITNESS_JOURNEY_PLACEHOLDER_RULE,
4		WITNESS_LIVE_BACKEND_SERVED_RULE,
5		WITNESS_LOOPBACK_BACKEND_RULE,
6		type WitnessGesture,
7		type WitnessJourneyPlaceholderDeclaration,
8		type WitnessLiveBackendServed,
9		type WitnessLoopbackBackendInventory,
10		type WitnessMockedNonLoopbackSeamEntry,
11	} from './witness-real-app.ts';
12	
13	/**
14	 * The cypress-realworld-app direct Witness browser proof — the corpus's first
15	 * live-backend stateful vertical.
16	 *
17	 * Every other vertical in the corpus serves a byte-frozen static tree and
18	 * nothing else; its whole proof is that the served bytes never change. This one
19	 * cannot be that shape and stay honest, because the application is a
20	 * peer-to-peer payment app whose journey is meaningful precisely BECAUSE it
21	 * mutates server state: it signs a fresh account up, moves money, and reads the
22	 * transaction back. So the invariants move rather than weaken. The frontend SPA
23	 * dist is still inventoried before and after the journey and must be
24	 * byte-identical; the live backend — the application's own Express-over-lowdb
25	 * server, spawned by the harness on a second bounded loopback origin — is
26	 * explicitly outside the byte inventory, re-seeded from its frozen snapshot
27	 * before every pass, and every request the page makes to it is counted in its
28	 * own loopback-backend category. Determinism under a mutating store is bought
29	 * two ways: the re-seed, and the generic placeholder normalization that replaces
30	 * the identifiers the server mints with stable tokens, so two passes produce one
31	 * semantic digest.
32	 *
33	 * This module is the schema and its parser only. No journey ran to produce this
34	 * unit's evidence; the runner and its published receipt are a separate unit.
35	 */
36	export const WITNESS_REACT_CYPRESS_RWA_SCHEMA =
37		'versionless.witness-react-cypress-rwa.v1' as const;
38	export const WITNESS_REACT_CYPRESS_RWA_RECEIPT_PATH =
39		'evidence/runs/witness-react-cypress-rwa/receipt.json' as const;
40	export const REACT_CYPRESS_RWA_FIXTURE = 'react-cypress-rwa' as const;
41	export const REACT_CYPRESS_RWA_APPLICATION = 'cypress-realworld-app' as const;
42	
43	/**
44	 * The immutable cypress-realworld-app source identity, bound here so the
45	 * browser-proof receipt cannot silently rebind itself to a different revision or
46	 * archive. Every value is the application's own, taken from the pinned tag.
47	 */
48	export const REACT_CYPRESS_RWA_SOURCE = Object.freeze({
49		repository: 'https://github.com/cypress-io/cypress-realworld-app',
50		ref: 'refs/tags/v1.0.18',
51		revision: 'f6b5cf3a1799998dab71181eeed59460f8ada5f4',
52		archiveSha256: 'bd9319272dabc1e7263a0186e0aaae011f6219e6e106363d2c89426f9357b315',
53		frontendRoot: '.',
54		backendRoot: 'backend',
55		license: 'MIT',
56		react: '17.0.2',
57		reactScripts: '4.0.3',
58		typescript: '4.3.4',
59	});
60	
61	/**
62	 * The stable placeholder tokens the journey normalizes its minted, server-decided
63	 * and seed-derived values to. Each is generic — a token and where the value
64	 * comes from — and deliberately carries NO literal value: the created ids are
65	 * decided by the server at run time, and `{recipient-handle}` is captured from a
66	 * seed user the money-movement step pays, then normalized away so no seed
67	 * identity ever reaches the evidence.
68	 */
69	export const WITNESS_REACT_CYPRESS_RWA_PLACEHOLDERS = Object.freeze([
70		Object.freeze({
71			token: '{created-user-id}',
72			origin: 'the id the backend mints for the freshly signed-up account',
73		}),
74		Object.freeze({
75			token: '{created-account-id}',
76			origin: 'the id the backend mints for the account onboarding creates',
77		}),
78		Object.freeze({
79			token: '{created-transaction-id}',
80			origin: 'the id the backend mints for the payment the journey sends',
81		}),
82		Object.freeze({
83			token: '{recipient-handle}',
84			origin: 'a seed user the payment is sent to, captured from search and normalized so no seed identity reaches the evidence',
85		}),
86	]) as readonly WitnessJourneyPlaceholderDeclaration[];
87	
88	/**
89	 * The deterministic, NON-SEED account the journey signs up and acts as. It is a
90	 * corpus identity invented for the proof, not a credential from the seed
91	 * database, so recording it discloses nothing the application ships. The
92	 * redaction test enforces that this is the only identity literal in the
93	 * evidence and that no seed username, password or hash appears anywhere.
94	 */
95	export const WITNESS_REACT_CYPRESS_RWA_ACTOR = Object.freeze({
96		firstName: 'Versionless',
97		lastName: 'Prover',
98		username: 'versionless-rwa-actor',
99		password: 'versionless-rwa-passphrase',
100	});
101	
102	/**
103	 * Seed-database markers that must never appear in the evidence. The bcrypt
104	 * prefixes are the shape of every hashed password in the seed; `s3cret` is the
105	 * seed's shared plaintext password. Their absence is the redaction proof, and
106	 * the parser fails the run if any of them is found in a recorded string.
107	 */
108	export const WITNESS_REACT_CYPRESS_RWA_FORBIDDEN_MARKERS = Object.freeze([
109		's3cret',
110		'$2a$',
111		'$2b$',
112		'$2y$',
113	]);
114	
115	/**
116	 * The exact route sequence the journey drives, in order, as the browser records
117	 * navigations AFTER the initial document load. The journey's initial load is a
118	 * real navigation to `/signup` (the signin page's signup link does not
119	 * SPA-navigate under automation), which the runtime does not record because the
120	 * navigation listener is attached once the first load has settled; the first
121	 * recorded entry is therefore the redirect to `/signin` the signup submit
122	 * triggers. Every segment is the literal path the live application navigated to —
123	 * measured, not declared: the payment does NOT redirect to a transaction-detail
124	 * route (it settles in place on `/transaction/new`), the public feed is the home
125	 * route `/`, and no server-minted identifier appears in any recorded route, so
126	 * the whole sequence is stable across passes without normalization. Pinning it is
127	 * what makes a dropped step or a silently redirected route fail the run.
128	 */
129	export const WITNESS_REACT_CYPRESS_RWA_ROUTES = Object.freeze([
130		'/signin',
131		'/',
132		'/user/settings',
133		'/transaction/new',
134		'/',
135		'/personal',
136		'/',
137		'/contacts',
138		'/personal',
139		'/notifications',
140	]);
141	
142	/**
143	 * The measured loopback-backend category: every endpoint the journey reaches on
144	 * the application's own server, by method and origin-relative path, read off the
145	 * live request ledger rather than declared from the Cypress specs. A request to
146	 * an endpoint outside this list fails the run. Paths that carry a server-minted
147	 * id use the placeholder token, so the category is comparable across runs the
148	 * same way the routes are.
149	 *
150	 * Three facts here are the live surface contradicting the spec-derived guess and
151	 * are the point of measuring: bank-account onboarding is a `POST /graphql`
152	 * mutation, not a `POST /bankAccounts` REST call, so `/graphql` is in and both
153	 * `/bankAccounts` reads are out; peer search is `GET /users` (with a query the
154	 * category drops), not `GET /users/search`; and the personal feed is
155	 * `GET /transactions`, while the journey never opens a transaction-detail route,
156	 * so neither `GET /transactions/{id}` nor `POST /logout` is ever reached. The
157	 * only minted id in the category is the settings write's `PATCH
158	 * /users/{created-user-id}`.
159	 */
160	export const WITNESS_REACT_CYPRESS_RWA_BACKEND_CATEGORY = Object.freeze([
161		Object.freeze({ method: 'GET', path: '/checkAuth' }),
162		Object.freeze({ method: 'GET', path: '/notifications' }),
163		Object.freeze({ method: 'GET', path: '/transactions' }),
164		Object.freeze({ method: 'GET', path: '/transactions/contacts' }),
165		Object.freeze({ method: 'GET', path: '/transactions/public' }),
166		Object.freeze({ method: 'GET', path: '/users' }),
167		Object.freeze({ method: 'PATCH', path: '/users/{created-user-id}' }),
168		Object.freeze({ method: 'POST', path: '/graphql' }),
169		Object.freeze({ method: 'POST', path: '/login' }),
170		Object.freeze({ method: 'POST', path: '/transactions' }),
171		Object.freeze({ method: 'POST', path: '/users' }),
172	]);
173	
174	/**
175	 * The application's one non-loopback seam: it renders every user's avatar from an
176	 * `<img src>` pointing at its own S3 SVG bucket. The witness host answers each in
177	 * context — none leaves the machine, so `successfulNonLoopback` stays zero — and
178	 * this is the exact, app-scoped declaration of which endpoints it is allowed to
179	 * reach: a request outside this set fails the seam inventory.
180	 *
181	 * The membership is the FULL set of seed-user avatar URLs, which is deterministic
182	 * because the seed is frozen. Pinning the complete set rather than the subset a
183	 * given run happens to render is what keeps the inventory stable: whichever seed
184	 * users a pass lays out, every avatar it fetches is a declared member and the
185	 * rest are recorded as explicitly absent. The freshly signed-up actor has no
186	 * avatar (signup sets none), so no per-run minted URL is ever fetched — the seam
187	 * set carries no minted value and needs no placeholder.
188	 */
189	export const WITNESS_REACT_CYPRESS_RWA_MOCKED_SEAMS = Object.freeze([
190		Object.freeze({
191			method: 'GET',
192			path: 'https://cypress-realworld-app-svgs.s3.amazonaws.com/24VniajY1y.svg',
193		}),
194		Object.freeze({
195			method: 'GET',
196			path: 'https://cypress-realworld-app-svgs.s3.amazonaws.com/bDjUb4ir5O.svg',
197		}),
198		Object.freeze({
199			method: 'GET',
200			path: 'https://cypress-realworld-app-svgs.s3.amazonaws.com/qywYp6hS0U.svg',
201		}),
202		Object.freeze({
203			method: 'GET',
204			path: 'https://cypress-realworld-app-svgs.s3.amazonaws.com/t45AiwidW.svg',
205		}),
206		Object.freeze({
207			method: 'GET',
208			path: 'https://cypress-realworld-app-svgs.s3.amazonaws.com/tsHF6_D5oQ.svg',
209		}),
210	]) as readonly WitnessMockedNonLoopbackSeamEntry[];
211	
212	export type WitnessReactCypressRwaSource = typeof REACT_CYPRESS_RWA_SOURCE;
213	
214	/** The SPA byte inventory for a live-backend run: scoped to the frontend dist only. */
215	export type WitnessReactCypressRwaServedStatic = {
216		transport: 'isolated-bounded-loopback-production-static';
217		documentFallback: 'index-only';
218		missingAssets: '404';
219		traversal: 'rejected';
220		inventory: { files: number; beforeSha256: string; afterSha256: string };
221		application: { path: 'index.html'; beforeSha256: string; afterSha256: string };
222		byteIdentical: true;
223		hmrControls: false;
224		liveBackend: WitnessLiveBackendServed;
225	};
226	
227	export type WitnessReactCypressRwaRun = {
228		app: typeof REACT_CYPRESS_RWA_APPLICATION;
229		framework: 'react';
230		lane: 'baseline' | 'migrated';
231		pass: 1 | 2;
232		result: 'pass';
233		interactions: Array<{ kind: WitnessGesture; selector: string }>;
234		assertions: string[];
235		routes: string[];
236		trackedEvents: string[];
237		witnessRecord: {
238			interactions: Array<{ kind: WitnessGesture; selector: string }>;
239			navigationPaths: string[];
240			trackedEventCounts: Record<string, number>;
241			consoleErrors: number;
242			pageErrors: number;
243			failedRequests: number;
244		};
245		cleanPage: true;
246		servedStatic: WitnessReactCypressRwaServedStatic;
247		loopbackBackend: WitnessLoopbackBackendInventory;
248		placeholders: readonly WitnessJourneyPlaceholderDeclaration[];
249		successfulNonLoopback: 0;
250		semanticDigest: string;
251		behaviorDigest: string;
252	};
253	
254	export type WitnessReactCypressRwaMutation = {
255		failure: 'witness-semantic-assertion';
256		intendedFailure: true;
257		lane: 'migrated';
258		seam: string;
259		path: string;
260		offset: number;
261		beforeSha256: string;
262		mutatedSha256: string;
263		afterRestoreSha256: string;
264		restoredByteIdentically: true;
265		restoredRun: 'pass';
266		restoredBehaviorDigest: string;
267	};
268	
269	export type WitnessReactCypressRwaReceipt = {
270		schemaVersion: typeof WITNESS_REACT_CYPRESS_RWA_SCHEMA;
271		result: 'pass';
272		fixture: typeof REACT_CYPRESS_RWA_FIXTURE;
273		application: typeof REACT_CYPRESS_RWA_APPLICATION;
274		framework: 'react';
275		source: WitnessReactCypressRwaSource;
276		provenance: Record<string, unknown>;
277		canonicalReceipt: { path: string; canonicalDigest: string; sha256: string };
278		runs: WitnessReactCypressRwaRun[];
279		mutation: WitnessReactCypressRwaMutation;
280		placeholders: readonly WitnessJourneyPlaceholderDeclaration[];
281		backendCategory: readonly { method: string; path: string }[];
282		determinism: {
283			reseededFromSnapshotBeforeEachPass: true;
284			mintedValuesPlaceholdered: true;
285			rule: typeof WITNESS_JOURNEY_PLACEHOLDER_RULE;
286		};
287		redaction: {
288			policy: 'no-seed-usernames-passwords-or-pii';
289			forbiddenMarkers: readonly string[];
290			actorIsNonSeedCorpusIdentity: true;
291		};
292		locality: {
293			mode: 'live-loopback-backend';
294			successfulNonLoopback: 0;
295			osWideIsolation: false;
296			rule: typeof WITNESS_LOOPBACK_BACKEND_RULE;
297		};
298		nonclaims: string[];
299		integrity: { algorithm: 'sha256'; canonicalDigest: string };
300	};
301	
302	const exact = (left: unknown, right: unknown): boolean =>
303		canonicalize(left) === canonicalize(right);
304	
305	function sha256Digest(value: unknown): value is string {
306		return typeof value === 'string' && value.length === 64;
307	}
308	
309	/**
310	 * The raw run digest: the whole run except the fields that identify a pass. Two
311	 * passes of the same lane re-seed to the same state and normalize the same
312	 * minted values, so this must be identical across a lane's passes.
313	 */
314	export function witnessReactCypressRwaRawDigest(run: WitnessReactCypressRwaRun): string {
315		const { pass: _pass, result: _result, semanticDigest: _semanticDigest, ...raw } = run;
316		const withoutBehavior = { ...raw } as Record<string, unknown>;
317		delete withoutBehavior.behaviorDigest;
318		return sha256(canonicalize(withoutBehavior));
319	}
320	
321	/**
322	 * The lane-independent behavior projection.
323	 *
324	 * Production SPA bytes are lane-specific by construction, so the byte inventory
325	 * stays in the run record and out of this digest; what remains is what both
326	 * lanes must share — the same journey, the same routes, the same backend
327	 * category shape, the same clean page. The loopback-backend inventory's admitted
328	 * total and category participate; the exact per-status observations do not,
329	 * because a lane's server build may answer a poll a different number of times.
330	 */
331	export function witnessReactCypressRwaBehaviorDigest(run: WitnessReactCypressRwaRun): string {
332		return sha256(
333			canonicalize({
334				app: run.app,
335				framework: run.framework,
336				interactions: run.interactions,
337				assertions: run.assertions,
338				routes: run.routes,
339				trackedEvents: run.trackedEvents,
340				witnessRecord: run.witnessRecord,
341				cleanPage: run.cleanPage,
342				servedStaticPolicy: {
343					transport: run.servedStatic.transport,
344					documentFallback: run.servedStatic.documentFallback,
345					missingAssets: run.servedStatic.missingAssets,
346					traversal: run.servedStatic.traversal,
347					byteIdentical: run.servedStatic.byteIdentical,
348					hmrControls: run.servedStatic.hmrControls,
349					liveBackend: run.servedStatic.liveBackend,
350				},
351				loopbackBackendPolicy: {
352					policy: run.loopbackBackend.policy,
353					backend: run.loopbackBackend.backend,
354					category: run.loopbackBackend.category,
355					outsideCategory: run.loopbackBackend.outsideCategory,
356					admitted: run.loopbackBackend.admitted,
357					successfulNonLoopback: run.loopbackBackend.successfulNonLoopback,
358				},
359				placeholders: run.placeholders,
360				successfulNonLoopback: run.successfulNonLoopback,
361			}),
362		);
363	}
364	
365	export function witnessReactCypressRwaDigest(receipt: WitnessReactCypressRwaReceipt): string {
366		const copy = structuredClone(receipt);
367		copy.integrity.canonicalDigest = '';
368		return sha256(canonicalize(copy));
369	}
370	
371	/**
372	 * Every string reachable in a value, so the redaction check can assert no seed
373	 * marker appears anywhere in the recorded evidence rather than in a hand-picked
374	 * subset of fields.
375	 */
376	function collectStrings(value: unknown, into: string[]): void {
377		if (typeof value === 'string') into.push(value);
378		else if (Array.isArray(value)) for (const item of value) collectStrings(item, into);
379		else if (value !== null && typeof value === 'object')
380			for (const item of Object.values(value)) collectStrings(item, into);
381	}
382	
383	function assertRedaction(run: WitnessReactCypressRwaRun, label: string): void {
384		const strings: string[] = [];
385		collectStrings(run, strings);
386		for (const text of strings)
387			for (const marker of WITNESS_REACT_CYPRESS_RWA_FORBIDDEN_MARKERS)
388				if (text.includes(marker))
389					throw new Error(`Cypress RWA Witness redaction leaked a seed marker: ${label}`);
390	}
391	
392	function assertServedStatic(served: WitnessReactCypressRwaServedStatic, label: string): void {
393		if (
394			served.transport !== 'isolated-bounded-loopback-production-static' ||
395			served.documentFallback !== 'index-only' ||
396			served.missingAssets !== '404' ||
397			served.traversal !== 'rejected' ||
398			!Number.isInteger(served.inventory?.files) ||
399			served.inventory.files < 1 ||
400			!sha256Digest(served.inventory.beforeSha256) ||
401			served.inventory.beforeSha256 !== served.inventory.afterSha256 ||
402			served.application?.path !== 'index.html' ||
403			!sha256Digest(served.application.beforeSha256) ||
404			served.application.beforeSha256 !== served.application.afterSha256 ||
405			served.byteIdentical !== true ||
406			served.hmrControls !== false ||
407			served.liveBackend?.backend !== 'live-loopback' ||
408			served.liveBackend.byteInventoryScope !== 'frontend-spa-dist' ||
409			served.liveBackend.rule !== WITNESS_LIVE_BACKEND_SERVED_RULE
410		)
411			throw new Error(`Cypress RWA Witness served-static differs: ${label}`);
412	}
413	
414	function assertLoopbackBackend(inventory: WitnessLoopbackBackendInventory, label: string): void {
415		if (
416			inventory?.policy !== 'live-first-party-loopback-backend' ||
417			inventory.backend !== 'live-loopback' ||
418			inventory.rule !== WITNESS_LOOPBACK_BACKEND_RULE ||
419			inventory.successfulNonLoopback !== 0 ||
420			!exact(inventory.outsideCategory, []) ||
421			!exact(inventory.category, WITNESS_REACT_CYPRESS_RWA_BACKEND_CATEGORY) ||
422			!Array.isArray(inventory.observed) ||
423			inventory.observed.length === 0 ||
424			inventory.admitted !== inventory.observed.reduce((sum, entry) => sum + entry.requests, 0)
425		)
426			throw new Error(`Cypress RWA Witness loopback-backend inventory differs: ${label}`);
427		const declared = new Set(
428			WITNESS_REACT_CYPRESS_RWA_BACKEND_CATEGORY.map((entry) => `${entry.method} ${entry.path}`),
429		);
430		for (const observation of inventory.observed)
431			if (!declared.has(`${observation.method} ${observation.path}`))
432				throw new Error(`Cypress RWA Witness backend observation is undeclared: ${label}`);
433	}
434	
435	export function parseWitnessReactCypressRwaReceipt(value: unknown): WitnessReactCypressRwaReceipt {
436		if (value === null || typeof value !== 'object' || Array.isArray(value))
437			throw new Error('Cypress RWA Witness receipt must be an object');
438		const receipt = value as WitnessReactCypressRwaReceipt;
439		const expectedRuns = new Set(['baseline:1', 'baseline:2', 'migrated:1', 'migrated:2']);
440		const behaviors = new Set<string>();
441		const semanticByLane = new Map<string, string>();
442		if (
443			receipt.schemaVersion !== WITNESS_REACT_CYPRESS_RWA_SCHEMA ||
444			receipt.result !== 'pass' ||
445			receipt.fixture !== REACT_CYPRESS_RWA_FIXTURE ||
446			receipt.application !== REACT_CYPRESS_RWA_APPLICATION ||
447			receipt.framework !== 'react' ||
448			!exact(receipt.source, REACT_CYPRESS_RWA_SOURCE) ||
449			!Array.isArray(receipt.runs) ||
450			receipt.runs.length !== 4 ||
451			!exact(receipt.placeholders, WITNESS_REACT_CYPRESS_RWA_PLACEHOLDERS) ||
452			!exact(receipt.backendCategory, WITNESS_REACT_CYPRESS_RWA_BACKEND_CATEGORY)
453		)
454			throw new Error('Cypress RWA Witness binding differs');
455		for (const run of receipt.runs) {
456			const key = `${run.lane}:${run.pass}`;
457			if (
458				!expectedRuns.delete(key) ||
459				run.app !== REACT_CYPRESS_RWA_APPLICATION ||
460				run.framework !== 'react' ||
461				run.result !== 'pass' ||
462				run.cleanPage !== true ||
463				run.successfulNonLoopback !== 0 ||
464				run.witnessRecord.pageErrors !== 0 ||
465				!Array.isArray(run.interactions) ||
466				run.interactions.length === 0 ||
467				!Array.isArray(run.assertions) ||
468				run.assertions.length === 0 ||
469				!exact(run.routes, WITNESS_REACT_CYPRESS_RWA_ROUTES) ||
470				!exact(run.placeholders, WITNESS_REACT_CYPRESS_RWA_PLACEHOLDERS) ||
471				run.semanticDigest !== witnessReactCypressRwaRawDigest(run) ||
472				run.behaviorDigest !== witnessReactCypressRwaBehaviorDigest(run)
473			)
474				throw new Error(`Cypress RWA Witness run differs: ${key}`);
475			assertServedStatic(run.servedStatic, key);
476			assertLoopbackBackend(run.loopbackBackend, key);
477			assertRedaction(run, key);
478			const priorSemantic = semanticByLane.get(run.lane);
479			if (priorSemantic !== undefined && priorSemantic !== run.semanticDigest)
480				throw new Error(`Cypress RWA Witness pass-twice semantic digest differs: ${run.lane}`);
481			semanticByLane.set(run.lane, run.semanticDigest);
482			behaviors.add(run.behaviorDigest);
483		}
484		if (
485			expectedRuns.size !== 0 ||
486			behaviors.size !== 1 ||
487			receipt.determinism?.reseededFromSnapshotBeforeEachPass !== true ||
488			receipt.determinism.mintedValuesPlaceholdered !== true ||
489			receipt.determinism.rule !== WITNESS_JOURNEY_PLACEHOLDER_RULE ||
490			receipt.redaction?.policy !== 'no-seed-usernames-passwords-or-pii' ||
491			receipt.redaction.actorIsNonSeedCorpusIdentity !== true ||
492			!exact(receipt.redaction.forbiddenMarkers, WITNESS_REACT_CYPRESS_RWA_FORBIDDEN_MARKERS) ||
493			receipt.mutation?.intendedFailure !== true ||
494			receipt.mutation.failure !== 'witness-semantic-assertion' ||
495			receipt.mutation.lane !== 'migrated' ||
496			receipt.mutation.restoredByteIdentically !== true ||
497			receipt.mutation.restoredRun !== 'pass' ||
498			receipt.mutation.beforeSha256 !== receipt.mutation.afterRestoreSha256 ||
499			receipt.mutation.beforeSha256 === receipt.mutation.mutatedSha256 ||
500			!behaviors.has(receipt.mutation.restoredBehaviorDigest) ||
501			receipt.locality?.mode !== 'live-loopback-backend' ||
502			receipt.locality.successfulNonLoopback !== 0 ||
503			receipt.locality.osWideIsolation !== false ||
504			receipt.locality.rule !== WITNESS_LOOPBACK_BACKEND_RULE ||
505			!Array.isArray(receipt.nonclaims) ||
506			receipt.nonclaims.length === 0 ||
507			receipt.integrity?.algorithm !== 'sha256' ||
508			receipt.integrity.canonicalDigest !== witnessReactCypressRwaDigest(receipt)
509		)
510			throw new Error('Cypress RWA Witness integrity or determinism differs');
511		return receipt;
512	}
513	
514	export function witnessReactCypressRwaAggregateMember(digestValue: string) {
515		return {
516			id: 'witness-react-cypress-rwa',
517			framework: 'react',
518			track: 'production-readiness-direct-witness-live-backend-create-react-app-to-vite8',
519			bundler: 'webpack-4.44.2-to-vite-8.0.16',
520			backend: 'live-loopback',
521			result: 'pass',
522			receipt: WITNESS_REACT_CYPRESS_RWA_RECEIPT_PATH,
523			digest: digestValue,
524		};
525	}
