42			canonicalReceipt: 'evidence/runs/react-cypress-rwa/rerun-2026-08-12/build-profile.json',
43			canonicalDigest: '981fbff5b2c8a4e257544bf6ba6abb25334c686fd56605edd6e0a89f4795d1ae',
44			canonicalBinding: 'file-sha256',
45			sources: {
