47				migrated: '.versionless/stage/witness-real-app/lanes/cypress-realworld-app/migrated',
48			},
49			// A real load to `/signup`: the signin page's signup link does not
50			// SPA-navigate under automation (measured), so the journey starts at the
51			// signup route directly and the SPA index fallback renders the SignUpForm.
52			initialRoute: '/signup',
53			/**
54			 * The application's own server. Command and port are the app's declared
55			 * ones; the harness copies the frozen seed over the mutable lowdb store and
56			 * runs the app's own prerequisite mock-config copy before boot, then waits
