62				args: ['start:api'],
63				cwd: '.',
64				port: 3001,
65				// The built SPA calls its backend absolutely at `http://localhost:3001`
66				// and the server's own CORS allow-origin is `http://localhost:<port>`, so
67				// the document has to be served under `localhost` too or every
68				// credentialed request is cross-origin. Both are the application's own
