87				migrated: WITNESS_REACT_CYPRESS_RWA_MOCKED_SEAMS,
88			},
89			// Non-loopback requests are answered in-context: the avatar SVGs get a
90			// decodable placeholder image so the page renders clean; anything else an
91			// empty 204. The host counts these as mockedNonLoopback and keeps
92			// successfulNonLoopback at zero.
93			transport: async (request) => {
94				if (request.pathname.endsWith('.svg'))
95					return {
96						action: 'fulfill',
97						status: 200,
98						contentType: 'image/svg+xml',
99						body: Buffer.from(CYPRESS_RWA_PLACEHOLDER_SVG),
100					};
