104				await page.trackEvents('click', 'input', 'change', 'keydown', 'mouseover');
105				const expectPage = context.expect.page;
106				// The MUI `data-test` on signup/signin/bankaccount/transaction-create is on
107				// the TextField ROOT, so the real <input> is `[data-test=…] input`; the
108				// settings and peer-search fields carry `data-test` on the <input> itself,
109				// so they are addressed without ` input`. Both are measured off the live DOM.
110	
111				// Auth — the initial load is a real navigation to `/signup`; sign a fresh
