115				await page.type('[data-test=signup-last-name] input', actor.lastName);
116				await page.type('[data-test=signup-username] input', actor.username);
117				await page.type('[data-test=signup-password] input', actor.password);
118				await page.type('[data-test=signup-confirmPassword] input', actor.password);
119				await page.click('[data-test=signup-submit]');
120				await expectPage.exists(page, '[data-test=signin-username] input');
121				await page.type('[data-test=signin-username] input', actor.username);
122				await page.type('[data-test=signin-password] input', actor.password);
123				await page.click('[data-test=signin-submit]');
124	
125				// Onboarding — the app's first-bank-account dialog (a POST /graphql
126				// mutation), then the actor completes its required settings so a mutating
127				// PATCH /users/{created-user-id} is proven before any transfer. A fresh
128				// actor has no email or phone, so Save stays disabled until both are set.
129				await expectPage.exists(page, '[data-test=user-onboarding-next]');
130				await page.click('[data-test=user-onboarding-next]');
131				await expectPage.exists(page, '[data-test=bankaccount-bankName-input] input');
132				await page.type('[data-test=bankaccount-bankName-input] input', 'Versionless Bank');
133				await page.type('[data-test=bankaccount-routingNumber-input] input', '987654321');
134				await page.type('[data-test=bankaccount-accountNumber-input] input', '123456789');
135				await page.click('[data-test=bankaccount-submit]');
136				await expectPage.exists(page, '[data-test=user-onboarding-next]');
137				await page.click('[data-test=user-onboarding-next]');
138				await expectPage.exists(page, '[data-test=sidenav-user-settings]');
139				await page.click('[data-test=sidenav-user-settings]');
140				await expectPage.exists(page, '[data-test=user-settings-email-input]');
141				await page.type('[data-test=user-settings-email-input]', 'prover@versionless.test');
142				await page.type('[data-test=user-settings-phoneNumber-input]', '6155551234');
143				await page.click('[data-test=user-settings-submit]');
144	
145				// Money movement — the substantive stateful step. Search a peer, pick the
146				// first result (its handle is captured and normalized, never recorded),
147				// and send a payment the backend mints an id for (POST /transactions).
148				await expectPage.exists(page, '[data-test=nav-top-new-transaction]');
149				await page.click('[data-test=nav-top-new-transaction]');
150				await expectPage.exists(page, '[data-test=user-list-search-input]');
151				await page.type('[data-test=user-list-search-input]', 'a');
152				await expectPage.exists(page, '[data-test^=user-list-item-]');
153				await page.click('[data-test^=user-list-item-]');
154				await expectPage.exists(page, '[data-test=transaction-create-amount-input] input');
155				await page.type('[data-test=transaction-create-amount-input] input', '15');
156				await page.type(
157					'[data-test=transaction-create-description-input] input',
158					'versionless-proof-payment',
159				);
160				await page.click('[data-test=transaction-create-submit-payment]');
161	
