172				// fresh actor, so its settled shape is the app's own empty-list marker.
173				await page.click('[data-test=nav-public-tab]');
174				await expectPage.exists(page, '[data-test=transaction-list]');
175				await page.click('[data-test=nav-contacts-tab]');
176				await expectPage.exists(
177					page,
178					'[data-test=transaction-list], [data-test=empty-list-header]',
179				);
